def solve(grid, start, goal):
    sr, sc = start
    gr, gc = goal
    if grid[sr][sc] == '#' or grid[gr][gc] == '#':
        return []
    if start == goal:
        return [start]
    rows, cols = len(grid), len(grid[0])
    visited = set()
    path = []

    def dfs(current):
        if current == goal:
            return True
        visited.add(current)
        path.append(current)
        directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                next_cell = (nr, nc)
                if grid[nr][nc] == '.' and next_cell not in visited:
                    if dfs(next_cell):
                        return True
        path.pop()
        visited.remove(current)
        return False

    if dfs(start):
        return path
    else:
        return []

