import heapq
import random

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    if not is_valid(*start) or not is_valid(*goal):
        return []

    visited = set()
    parent = {}
    heap = []
    heapq.heappush(heap, (random.random(), start))
    parent[start] = None

    while heap:
        _, current = heapq.heappop(heap)
        if current == goal:
            break
        if current in visited:
            continue
        visited.add(current)
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if is_valid(r, c) and (r, c) not in visited:
                if (r, c) not in parent:
                    heapq.heappush(heap, (random.random(), (r, c)))
                    parent[(r, c)] = current

    # Reconstruct path
    if goal not in parent:
        return []

    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = parent[current]
    path.reverse()
    return path

