import heapq
import random

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    if start == goal:
        return [start] if is_valid(start) else []

    if not is_valid(start) or not is_valid(goal):
        return []

    visited = set()
    parent = {}
    heap = []
    heapq.heappush(heap, (random.random(), start))

    while heap:
        _, current = heapq.heappop(heap)
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            break
        r, c = current
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            next_cell = (nr, nc)
            if is_valid(next_cell) and next_cell not in visited:
                heapq.heappush(heap, (random.random(), next_cell))
                if next_cell not in parent:
                    parent[next_cell] = current

    if goal not in visited:
        return []

    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = parent[curr]
    path.append(start)
    path.reverse()
    return path

