import heapq

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_valid(point):
        r, c = point
        return 0 <= r < rows and 0 <= c < cols

    if not is_valid(start) or not is_valid(goal):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    pq = []
    heapq.heappush(pq, (0, start[0], start[1]))
    distances = {(start[0], start[1]): 0}
    parents = {}

    while pq:
        dist, r, c = heapq.heappop(pq)
        current = (r, c)
        if current == goal:
            path = []
            curr = current
            while curr in parents:
                path.append(curr)
                curr = parents[curr]
            path.append(start)
            return path[::-1]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            next_cell = (nr, nc)
            if is_valid(next_cell) and grid[nr][nc] == '.':
                new_dist = dist + 1
                if next_cell not in distances or new_dist < distances[next_cell]:
                    distances[next_cell] = new_dist
                    parents[next_cell] = current
                    heapq.heappush(pq, (new_dist, nr, nc))

    return []

