def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    if not is_valid(*start) or not is_valid(*goal):
        return []
    if start == goal:
        return [start]

    reachable = [[False] * cols for _ in range(rows)]
    gr, gc = goal
    reachable[gr][gc] = True

    changed = True
    while changed:
        changed = False
        for i in range(rows):
            for j in range(cols):
                if (i, j) == (gr, gc):
                    continue
                if grid[i][j] == '.' and not reachable[i][j]:
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ni, nj = i + dx, j + dy
                        if 0 <= ni < rows and 0 <= nj < cols:
                            if reachable[ni][nj]:
                                reachable[i][j] = True
                                changed = True
                                break

    if not reachable[start[0]][start[1]]:
        return []

    path = [start]
    current = start
    visited = { (current[0], current[1]) }
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    while current != goal:
        found = False
        for dr, dc in directions:
            nr = current[0] + dr
            nc = current[1] + dc
            if is_valid(nr, nc) and reachable[nr][nc] and (nr, nc) not in visited:
                path.append((nr, nc))
                visited.add((nr, nc))
                current = (nr, nc)
                found = True
                break
        if not found:
            return []

    return path

