    def is_clear_row(r, c1, c2):
        min_c = min(c1, c2)
        max_c = max(c1, c2)
        for c in range(min_c, max_c + 1):
            if grid[r][c] == '#':
                return False
        return True

    def is_clear_col(c, r1, r2):
        min_r = min(r1, r2)
        max_r = max(r1, r2)
        for r in range(min_r, max_r + 1):
            if grid[r][c] == '#':
                return False
        return True

    # Check same row
    if sr == gr:
        if is_clear_row(sr, sc, gc):
            step = 1 if gc > sc else -1
            return [(sr, c) for c in range(sc, gc + step, step)]
